+      margin-bottom: 20px;
+      padding: 20px;
+      background: var(--panel-2);
+      border: 1px solid var(--border);
+      border-radius: 18px;
+    }
+
+    .question-title {
+      margin: 0 0 6px;
+      font-size: 1.05rem;
+      font-weight: 700;
+    }
+
+    .help-text {
+      margin: 0 0 14px;
+      color: var(--muted);
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    .choices {
+      display: grid;
+      gap: 10px;
+    }
+
+    .choice {
+      display: flex;
+      align-items: center;
+      gap: 12px;
+      padding: 14px 16px;
+      border-radius: 14px;
+      border: 1px solid rgba(159, 176, 208, 0.16);
+      background: rgba(255, 255, 255, 0.02);
+      transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
+      cursor: pointer;
+    }
+
+    .choice:hover {
+      transform: translateY(-1px);
+      border-color: rgba(124, 156, 255, 0.42);
+      background: rgba(124, 156, 255, 0.08);
+    }
+
+    .choice input {
+      width: 18px;
+      height: 18px;
+      accent-color: var(--accent);
+      flex: 0 0 auto;
+    }
+
+    .choice span {
+      line-height: 1.4;
+    }
+
+    .actions {
+      display: flex;
+      gap: 14px;
+      align-items: center;
+      margin-top: 24px;
+      flex-wrap: wrap;
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 999px;
+      padding: 14px 22px;
+      font: inherit;
+      font-weight: 700;
+      color: white;
+      background: linear-gradient(135deg, var(--accent), var(--accent-2));
+      box-shadow: 0 14px 30px rgba(124, 156, 255, 0.25);
+      cursor: pointer;
+    }
+
+    button:hover { filter: brightness(1.05); }
+
+    .result {
+      min-height: 1.5em;
+      color: var(--success);
+      font-weight: 600;
+    }
+
+    @media (max-width: 640px) {
+      .hero, form { padding-left: 18px; padding-right: 18px; }
+      .form-field { padding: 16px; }
+    }
+  </style>
+</head>
+<body>
+  <div id="root"></div>
+
+  <script>
+    const quizData = [
+      {
+        id: "q1",
+        title: "Which of these are programming languages?",
+        helpText: "Select every option that is commonly used to write software.",
+        options: ["Python", "HTML", "JavaScript", "CSS"]
+      },
+      {
+        id: "q2",
+        title: "Which of these are compiled languages?",
+        options: ["C", "Go", "Ruby", "Rust"]
+      },
+      {
+        id: "q3",
+        title: "Which of these are used for web development?",
+        options: ["TypeScript", "PHP", "Swift", "SQL"]
+      }
+    ];
+
+    const quizComponents = {
+      App() {
+        return `
+          <main class="app">
+            ${this.Hero()}
+            ${this.Form()}
+          </main>
+        `;
+      },
+      Hero() {
+        return `
+          <header class="hero">
+            <p class="eyebrow">Quiz Challenge</p>
+            <h1>Computer Languages</h1>
+            <p class="subtext">Choose all answers that apply for each question. Each question supports multiple selections.</p>
+          </header>
+        `;
+      },
+      Form() {
+        return `
+          <form id="quiz-form">
+            ${quizData.map((question) => this.Question(question)).join("")}
+            <div class="actions">
+              <button type="submit">Submit Quiz</button>
+              <div class="result" id="result" aria-live="polite"></div>
+            </div>
+          </form>
+        `;
+      },
+      Question(question) {
+        return `
+          <div class="form-field">
+            <h2 class="question-title">${question.title}</h2>
+            ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
+            <div class="choices">
+              ${question.options.map((option, index) => {
+                const id = `${question.id}-${index}`;
+                return `
+                  <label class="choice" for="${id}">
+                    <input type="checkbox" id="${id}" name="${question.id}" value="${option}" />
+                    <span>${option}</span>
+                  </label>
+                `;
+              }).join("")}
+            </div>
+          </div>
+        `;
+      }
+    };
+
+    document.getElementById("root").innerHTML = quizComponents.App();
+
+    document.getElementById("quiz-form").addEventListener("submit", (event) => {
+      event.preventDefault();
+      const result = document.getElementById("result");
+      const selected = quizData.map((question) => {
+        const values = [...document.querySelectorAll(`input[name="${question.id}"]:checked`)].map((input) => input.value);
+        return `${question.id.toUpperCase()}: ${values.length ? values.join(", ") : "no selection"}`;
+      });
+      result.textContent = `Selections saved — ${selected.join(" | ")}`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
