      margin: 0 0 10px;
      color: var(--accent);
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1.1;
    }

    .subtext {
      margin: 12px 0 0;
      max-width: 62ch;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      padding: 24px 32px 32px;
    }

    .form-field {
      margin-bottom: 20px;
      padding: 20px;
      background: var(--panel-2);
      border: 1px solid var(--border);
      border-radius: 18px;
    }

    .question-title {
      margin: 0 0 6px;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .help-text {
      margin: 0 0 14px;
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.5;
    }

    .choices {
      display: grid;
      gap: 10px;
    }

    .choice {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 16px;
      border-radius: 14px;
      border: 1px solid rgba(159, 176, 208, 0.16);
      background: rgba(255, 255, 255, 0.02);
      transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
      cursor: pointer;
    }

    .choice:hover {
      transform: translateY(-1px);
      border-color: rgba(124, 156, 255, 0.42);
      background: rgba(124, 156, 255, 0.08);
